#include <stdio.h>
#include <string.h>
#include <stdlib.h>

void escape(char *str) {
    int len = strlen(str);
    char *out = malloc(len * 2 + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] == '\') {
            out[j++] = '\';
            out[j++] = '\';
        } else if (str[i] == '\n') {
            out[j++] = '\';
            out[j++] = 'n';
        } else {
            out[j++] = str[i];
        }
    }
    out[j] = '\0';
    printf("%s\n", out);
    free(out);
}

void unescape(char *str) {
    int len = strlen(str);
    char *out = malloc(len + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] == '\') {
            if (i + 1 < len) {
                if (str[i + 1] == '\') {
                    out[j++] = '\';
                    i++;
                } else if (str[i + 1] == 'n') {
                    out[j++] = '\n';
                    i++;
                }
            }
        } else {
            out[j++] = str[i];
        }
    }
    out[j] = '\0';
    printf("%s\n", out);
    free(out);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "escape") == 0) {
        if (argc < 3) {
            printf("USAGE\n");
            return 0;
        }
        escape(argv[2]);
    } else if (strcmp(argv[1], "unescape") == 0) {
        if (argc < 3) {
            printf("USAGE\n");
            return 0;
        }
        unescape(argv[2]);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
